<?php require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/auth.php';require_login();$eps=$pdo->query('SELECT * FROM elemen_penilaian ORDER BY urutan')->fetchAll();$pics=$pdo->query('SELECT * FROM pic WHERE aktif=1 ORDER BY nama')->fetchAll();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$nama=trim($_POST['nama']??'');$ep_id=(int)($_POST['ep_id']??0);$pic_id=(int)($_POST['pic_id']??0)?:null;$versi=trim($_POST['versi']??'1.0');$review=$_POST['tanggal_review']??null;$kategori=trim($_POST['kategori']??'SOP');if($nama===''||!$ep_id||empty($_FILES['file']['name']))$error='Nama, EP dan file wajib diisi.';else{$ext=strtolower(pathinfo($_FILES['file']['name'],PATHINFO_EXTENSION));$allowed=['pdf','doc','docx','xls','xlsx','png','jpg','jpeg'];if(!in_array($ext,$allowed,true))$error='Jenis file tidak diizinkan.';else{$dir=__DIR__.'/../uploads';if(!is_dir($dir))mkdir($dir,0775,true);$name=uniqid('doc_',true).'.'.$ext;if(move_uploaded_file($_FILES['file']['tmp_name'],$dir.'/'.$name)){$pdo->beginTransaction();$st=$pdo->prepare('INSERT INTO dokumen(nama,kategori,versi,tanggal_review,filename,original_name,status,pic_id,created_by) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([$nama,$kategori,$versi,$review,$name,$_FILES['file']['name'],'lengkap',$pic_id,$_SESSION['user']['id']]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO dokumen_ep(dokumen_id,ep_id) VALUES(?,?)')->execute([$id,$ep_id]);$pdo->prepare('INSERT INTO dokumen_versi(dokumen_id,versi,filename,original_name,catatan,created_by) VALUES(?,?,?,?,?,?)')->execute([$id,$versi,$name,$_FILES['file']['name'],'Versi awal',$_SESSION['user']['id']]);$pdo->commit();$kode=$pdo->prepare('SELECT kode FROM elemen_penilaian WHERE id=?');$kode->execute([$ep_id]);header('Location:/MRMIKIT/mode-survei/detail.php?kode='.urlencode($kode->fetchColumn()));exit;}$error='Gagal menyimpan file.';}}} $page_title='Tambah Dokumen';require __DIR__.'/../partials/header.php';?><h2>Tambah Dokumen & Kaitkan EP</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><div class="card shadow-sm border-0"><div class="card-body"><form method="post" enctype="multipart/form-data"><div class="mb-3"><label>Nama Dokumen</label><input class="form-control" name="nama" required></div><div class="row"><div class="col-md-6 mb-3"><label>EP MRMIK</label><select class="form-select" name="ep_id" required><option value="">Pilih EP</option><?php foreach($eps as $e):?><option value="<?=$e['id']?>"><?=htmlspecialchars($e['kode'].' — '.$e['judul'])?></option><?php endforeach;?></select></div><div class="col-md-6 mb-3"><label>PIC</label><select class="form-select" name="pic_id"><option value="">Belum ditentukan</option><?php foreach($pics as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['nama'].' — '.$p['unit'])?></option><?php endforeach;?></select></div></div><div class="row"><div class="col-md-4 mb-3"><label>Kategori</label><select class="form-select" name="kategori"><option>SOP</option><option>Kebijakan</option><option>Pedoman</option><option>SK</option><option>Laporan</option><option>Formulir</option></select></div><div class="col-md-4 mb-3"><label>Versi</label><input class="form-control" name="versi" value="1.0"></div><div class="col-md-4 mb-3"><label>Tanggal Review</label><input class="form-control" type="date" name="tanggal_review"></div></div><div class="mb-3"><label>File</label><input class="form-control" type="file" name="file" required></div><button class="btn btn-success">Simpan & Hubungkan EP</button></form></div></div><?php require __DIR__.'/../partials/footer.php';